function solve(s) {
  const n = s.length;
  let count = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i; j < n; j++) {
      let lo = i;
      let hi = j;
      let ok = true;
      while (lo < hi) {
        if (s[lo] !== s[hi]) {
          ok = false;
          break;
        }
        lo++;
        hi--;
      }
      if (ok) count++;
    }
  }
  return count;
}

function solve(s) {
  const n = s.length;
  let count = 0;
  for (let c = 0; c < n; c++) {
    let lo = c;
    let hi = c;
    while (lo >= 0 && hi < n && s[lo] === s[hi]) {
      count++;
      lo--;
      hi++;
    }
    lo = c;
    hi = c + 1;
    while (lo >= 0 && hi < n && s[lo] === s[hi]) {
      count++;
      lo--;
      hi++;
    }
  }
  return count;
}
